#nullable enable
using System.Text.Json;
using Alba;
using JasperFx.Core;
using Microsoft.Extensions.DependencyInjection;
using HourBooking.Contracts;
using HourBooking.Slices.Booking;
using Shouldly;
using Wolverine;
using Wolverine.Tracking;
