namespace HourBooking.IntegrationTests.Slices.Booking;

/// <summary>
/// Generated from the model's GWT cells, NOT from the implementation — which is the only reason these
/// tests mean anything. Pattern: automation. Status: in-progress. LIVE: this slice is claimed, so every
/// test here must pass.
///
/// The first automation slice, so the WHEN is not a screen posting a form. Two different WHENs appear
/// here and the difference is the pattern:
///
///   Tick()   — the automated trigger runs. This is what the model's ZeroFillProcessor is: it reads the
///              ZeroFillTodo and WorkingDays views and issues the commands. The rules about WHICH days
///              get filled (GWT 1 and 2) are only observable through it.
///   Invoke() — the command on its own, straight to the decider. A GWT's when= names a COMMAND, so the
///              rule that rejects one (GWT 4) is asserted by issuing one.
///
/// The GIVEN for three of the four is in SeedData: EmployeeRemovedFromProject and WorkingDayPublished
/// are both foreign events (origin="genesis seed" / "Google Calendar"), so seeding is the only honest
/// way they can exist. SeedData's removal from LeftProjectId, effective the 3rd, is therefore already
/// one pending ZeroFillTodo row in every test — which is why every assertion filters by projectId.
/// </summary>
public sealed class FillZeroHoursTests(AppFixture fixture) : IntegrationContext(fixture)
{
    private static readonly JsonSerializerOptions Json = new(JsonSerializerDefaults.Web);

    private static string Timesheet(Guid employeeId) => FillZeroHoursState.StreamKey(employeeId, SeedData.Month);
    private static string MonthClosure => MonthGate.StreamKey(SeedData.EmployeeId, SeedData.Month);

    private static BookingMonthStarted MonthOpened =>
        new(SeedData.EmployeeId, SeedData.EmployeeName, SeedData.Month, SeedData.SeededAt);

    /// <summary>
    /// WHEN the automation runs: one sweep of the ZeroFillProcessor.
    ///
    /// The trigger is a Wolverine MESSAGE handler, so this sends the message — it does not post to the
    /// operator route. That matters more than it looks: while the trigger was an HTTP endpoint, the test
    /// seam and the production mechanism were the same thing, so "nothing ever wakes this in production"
    /// was invisible to a green suite. Driving the message means the test exercises what the heartbeat
    /// exercises, and the route is left as what it actually is — a convenience for an operator.
    ///
    /// It returns nothing, because the trigger returns nothing: a Wolverine handler's return value is a
    /// CASCADING MESSAGE, and a ZeroFillRun coming back from a fire-and-forget sweep could not be routed,
    /// which killed the whole outgoing batch. So assertions here are against the event stream — the truth
    /// anyway; the run report is operator observability, reachable over the operator route.
    ///
    /// The clock is absent in tests by design (AppFixture sets Automation:Heartbeat=false), so calling
    /// this IS the beat as far as a test is concerned.
    /// </summary>
    private async Task Tick()
    {
        using var scope = Host.Services.CreateScope();
        var bus = scope.ServiceProvider.GetRequiredService<IMessageBus>();
        await bus.InvokeAsync(new RunFillZeroHours());
    }

    /// <summary>
    /// WHEN the command alone: what the processor does per day, without the processor's day selection.
    /// The decider is a Wolverine message handler, not an HTTP endpoint, because nobody types this
    /// command — so the test issues it the same way the automation does.
    /// </summary>
    private async Task<ZeroFillOutcome> Invoke(FillZeroHours command)
    {
        using var scope = Host.Services.CreateScope();
        var bus = scope.ServiceProvider.GetRequiredService<IMessageBus>();
        return await bus.InvokeAsync<ZeroFillOutcome>(command);
    }

    /// <summary>What a PERSON does, for the one GWT that is about the difference.</summary>
    private async Task<IScenarioResult> Book(DateOnly date, decimal hours, Guid projectId)
    {
        var (_, result) = await WhenPosting(x =>
        {
            x.Post.Json(new BookHours(
                    Guid.NewGuid(), SeedData.EmployeeId, SeedData.Month, projectId, date, hours, null))
                .ToUrl($"/timesheet/{SeedData.EmployeeId}/{SeedData.Month}/bookings");
            x.IgnoreStatusCode();
        });
        return result;
    }

    private async Task<List<ZeroHoursFilled>> Filled(Guid employeeId, Guid projectId) =>
        (await EventsFor(Timesheet(employeeId)))
            .OfType<ZeroHoursFilled>()
            .Where(e => e.ProjectId == projectId)
            .ToList();

    // leaving a project fills the rest of that month with zero hours, one event per day
    //   GIVEN EmployeeRemovedFromProject
    //   WHEN  FillZeroHours
    //   THEN  ZeroHoursFilled
    [Fact]
    public async Task LeavingAProjectFillsTheRestOfThatMonthWithZeroHours()
    {
        // A removal in the middle of the month, so "the rest of that month" has a before and an after.
        await Given(SeedData.MembershipStream(SeedData.EmployeeId, SeedData.ProjectId),
            new EmployeeRemovedFromProject(
                SeedData.EmployeeId, SeedData.ProjectId, SeedData.MidMonthRemoval, SeedData.SeededAt));

        await Tick();

        var expected = SeedData.PublishedWorkingDays.Where(d => d >= SeedData.MidMonthRemoval).ToList();
        var filled = await Filled(SeedData.EmployeeId, SeedData.ProjectId);

        // ONE EVENT PER DAY: one per working day from the removal to month end, and no day twice.
        filled.Select(e => e.Date).ShouldBe(expected);
        filled.Select(e => e.BookingId).Distinct().Count().ShouldBe(filled.Count);
        filled.ShouldAllBe(e => e.Hours == 0m);
        filled.ShouldAllBe(e => e.Month == SeedData.Month);
        filled.ShouldAllBe(e => e.EmployeeId == SeedData.EmployeeId);

        // The other side of the boundary: the working days BEFORE the removal are untouched, which is
        // the only thing that proves "the rest of the month" rather than "the month".
        filled.ShouldAllBe(e => e.Date >= SeedData.MidMonthRemoval);
        SeedData.PublishedWorkingDays.ShouldContain(SeedData.WorkingDay);   // there were earlier ones
        filled.ShouldNotContain(e => e.Date == SeedData.WorkingDay);
    }

    // only working days are filled — weekends and public holidays are not
    //   GIVEN EmployeeRemovedFromProject, WorkingDayPublished
    //   WHEN  FillZeroHours
    //   THEN  ZeroHoursFilled
    [Fact]
    public async Task OnlyWorkingDaysAreFilledWeekendsAndPublicHolidaysAreNot()
    {
        // GIVEN is SeedData: removed from LeftProjectId effective the 3rd, and one WorkingDayPublished
        // per working day of the month from the Hungarian calendar.
        await Tick();

        var dates = (await Filled(SeedData.EmployeeId, SeedData.LeftProjectId)).Select(e => e.Date).ToList();

        dates.ShouldBe(SeedData.PublishedWorkingDays.Where(d => d >= SeedData.WorkingDay).ToList());

        // Both sides of the boundary, and the accepted case is the one that proves the exclusion is a
        // calendar lookup rather than DayOfWeek arithmetic:
        dates.ShouldNotContain(SeedData.Weekend);          // a Saturday, unpublished
        dates.ShouldNotContain(SeedData.PublicHoliday);    // a weekday, unpublished
        dates.ShouldContain(SeedData.WorkingSaturday);     // a Saturday the calendar DID publish
    }

    // the system may write a zero where an employee may not
    //   GIVEN EmployeeRemovedFromProject
    //   WHEN  FillZeroHours
    //   THEN  ZeroHoursFilled
    [Fact]
    public async Task TheSystemMayWriteAZeroWhereAnEmployeeMayNot()
    {
        await Given(MonthClosure, MonthOpened);

        // A person may never book zero — HoursMustBeNonZero, enforce="periphery", refused by the
        // FluentValidation middleware before any stream is touched.
        (await Book(SeedData.WorkingDay, 0m, SeedData.ProjectId))
            .Context.Response.StatusCode.ShouldBe(400);

        // And a person may not book at all on a project they have left — NotAProjectMember.
        (await Book(SeedData.WorkingDay, 8m, SeedData.LeftProjectId))
            .Context.Response.StatusCode.ShouldBe(400);

        (await EventsFor(Timesheet(SeedData.EmployeeId))).ShouldBeEmpty();

        // The automation writes exactly what both of those refuse: zero hours, on the project the
        // employee has left. It reaches the same stream through a different command, so it passes
        // through neither BookHoursValidator nor the membership check.
        await Tick();

        var filled = await Filled(SeedData.EmployeeId, SeedData.LeftProjectId);
        filled.ShouldNotBeEmpty();
        filled.ShouldAllBe(e => e.Hours == 0m);
        filled.ShouldContain(e => e.Date == SeedData.WorkingDay);
    }

    // a day already zero-filled is not filled twice
    //   GIVEN ZeroHoursFilled
    //   WHEN  FillZeroHours
    //   THEN  error: AlreadyFilled
    [Fact]
    public async Task ADayAlreadyZeroFilledIsNotFilledTwice()
    {
        // GIVEN one day of SeedData's pending row already zero-filled. Appended straight to the stream:
        // a GIVEN is history, not a request to replay.
        await Given(Timesheet(SeedData.EmployeeId), new ZeroHoursFilled(
            Guid.NewGuid(), SeedData.EmployeeId, SeedData.Month, SeedData.LeftProjectId,
            SeedData.WorkingDay, 0m, SeedData.SeededAt));

        // WHEN the command is issued for that day anyway.
        var outcome = await Invoke(new FillZeroHours(
            Guid.NewGuid(), SeedData.EmployeeId, SeedData.Month, SeedData.LeftProjectId,
            SeedData.WorkingDay, 0m));

        outcome.WasFilled.ShouldBeFalse();
        outcome.Rule.ShouldBe("AlreadyFilled");

        var forThatDay = (await Filled(SeedData.EmployeeId, SeedData.LeftProjectId))
            .Where(e => e.Date == SeedData.WorkingDay)
            .ToList();
        forThatDay.ShouldHaveSingleItem().FilledAt.ShouldBe(SeedData.SeededAt);   // the original stands

        // And the processor never gets that far: the ZeroHoursFilled ticked the day off the todo row,
        // so the tick does not even ask. The rest of the month still fills — the accepted side of the
        // boundary, without which "not twice" could just as well mean "never".
        await Tick();

        var afterTick = await Filled(SeedData.EmployeeId, SeedData.LeftProjectId);
        afterTick.Count(e => e.Date == SeedData.WorkingDay).ShouldBe(1);          // still only the one
        afterTick.ShouldContain(e => e.Date == SeedData.SecondWorkingDay);        // the rest still fills
    }

    // a day that already carries booked hours is left alone
    //   GIVEN HoursBooked
    //   WHEN  FillZeroHours
    //   THEN  error: AlreadyBooked
    //
    // Added AFTER this slice was implemented and green — the domain expert, asked whether a zero may be
    // written over hand-booked hours, said no. The test file is scaffold, so no test was generated for
    // it; codegen reported it as a GWT WITHOUT A TEST instead. See ANTI-PATTERNS.md #13.
    [Fact]
    public async Task ADayThatAlreadyCarriesBookedHoursIsLeftAlone()
    {
        // GIVEN a hand booking on one day of SeedData's pending row. Appended straight to the stream:
        // a GIVEN is history, not a request to replay — and a person could not have posted this one
        // anyway, because they have left LeftProjectId and NotAProjectMember would refuse it.
        await Given(Timesheet(SeedData.EmployeeId), new HoursBooked(
            Guid.NewGuid(), SeedData.EmployeeId, SeedData.Month, SeedData.LeftProjectId,
            SeedData.WorkingDay, 8m, null, SeedData.SeededAt));

        var outcome = await Invoke(new FillZeroHours(
            Guid.NewGuid(), SeedData.EmployeeId, SeedData.Month, SeedData.LeftProjectId,
            SeedData.WorkingDay, 0m));

        outcome.WasFilled.ShouldBeFalse();

        // AlreadyBooked, NOT AlreadyFilled. Splitting those two names is the whole point of this rule:
        // a caller that cannot tell "I already did this" from "a human already did this" cannot act
        // differently on them, and before the split both cases returned AlreadyFilled.
        outcome.Rule.ShouldBe("AlreadyBooked");

        // The person's 8 hours still stand, and no zero was written beside them.
        (await Filled(SeedData.EmployeeId, SeedData.LeftProjectId))
            .ShouldNotContain(e => e.Date == SeedData.WorkingDay);

        var booked = (await EventsFor(Timesheet(SeedData.EmployeeId))).OfType<HoursBooked>().ToList();
        booked.ShouldHaveSingleItem().Hours.ShouldBe(8m);

        // The accepted side of the boundary. Without it, "left alone" could equally mean "never fills",
        // and the day-by-day nature matters: only the booked day is refused, and the rest of the month
        // fills as normal.
        await Tick();

        var afterTick = await Filled(SeedData.EmployeeId, SeedData.LeftProjectId);
        afterTick.ShouldNotContain(e => e.Date == SeedData.WorkingDay);      // the booked day, left alone
        afterTick.ShouldContain(e => e.Date == SeedData.SecondWorkingDay);   // the rest still fills
    }

    // a closed month is not zero-filled either
    //   GIVEN MonthClosed
    //   WHEN  FillZeroHours
    //   THEN  error: MonthIsClosed
    //
    // Also added after the fact, from the expert's "yes" to whether a closed month blocks a zero-fill.
    // The automation is not privileged: it meets the same gate book-hours, correct-hours and
    // remove-booking meet.
    [Fact]
    public async Task AClosedMonthIsNotZeroFilledEither()
    {
        // The accepted side FIRST, on the same fixture, because it is the only thing that proves the
        // refusal below comes from the closure rather than from the fill never working here at all.
        await Given(MonthClosure, MonthOpened);

        var opened = await Invoke(new FillZeroHours(
            Guid.NewGuid(), SeedData.EmployeeId, SeedData.Month, SeedData.LeftProjectId,
            SeedData.WorkingDay, 0m));
        opened.WasFilled.ShouldBeTrue();
        opened.Rule.ShouldBeNull();

        // GIVEN the month is then closed. MonthClosed lives in the MonthClosure stream — a different
        // stream from Timesheet, keyed the same (employeeId, month). Appending it to the Timesheet
        // stream would leave the gate unable to see it and the test would pass for the wrong reason.
        await Given(MonthClosure, new MonthClosed(
            SeedData.EmployeeId, SeedData.Month, SeedData.AdminId, null, SeedData.SeededAt));

        var closed = await Invoke(new FillZeroHours(
            Guid.NewGuid(), SeedData.EmployeeId, SeedData.Month, SeedData.LeftProjectId,
            SeedData.SecondWorkingDay, 0m));

        closed.WasFilled.ShouldBeFalse();
        closed.Rule.ShouldBe("MonthIsClosed");

        // Nothing was appended for the refused day, and the day filled before the closure still stands.
        var filled = await Filled(SeedData.EmployeeId, SeedData.LeftProjectId);
        filled.ShouldNotContain(e => e.Date == SeedData.SecondWorkingDay);
        filled.ShouldContain(e => e.Date == SeedData.WorkingDay);

        // And the automation's own tick writes nothing into a closed month either — the rule holds on
        // the path that actually runs in production, not only on a direct invoke.
        var before = (await Filled(SeedData.EmployeeId, SeedData.LeftProjectId)).Count;
        await Tick();
        (await Filled(SeedData.EmployeeId, SeedData.LeftProjectId)).Count.ShouldBe(before);
    }

    /// <summary>
    /// NOT a GWT — the model says nothing about transport, and it should not. This asserts the two
    /// properties that make repeated, unattended sweeping safe, which is what the pattern actually needs
    /// from the sweep once the clock lives in AutomationHeartbeat and not here.
    ///
    /// What this does NOT assert is the clock. AppFixture switches the heartbeat off, because a sweep
    /// firing on its own mid-test would append events into streams other slices are asserting on. The
    /// clock is verified by running the app and watching a second sweep arrive — see ANTI-PATTERNS #14,
    /// which exists because a green suite proved nothing about it.
    /// </summary>
    [Fact]
    public async Task RepeatedSweepingIsSafeSoAClockCanDriveIt()
    {
        // IDEMPOTENT. The heartbeat sweeps forever, so the second sweep must be a no-op rather than a
        // second set of bookings. This is the property that makes the interval a free choice: correctness
        // cannot depend on how often the clock ticks, or on two ticks overlapping.
        await Tick();
        var afterFirst = await Filled(SeedData.EmployeeId, SeedData.LeftProjectId);
        afterFirst.ShouldNotBeEmpty();

        await Tick();
        await Tick();

        var afterThree = await Filled(SeedData.EmployeeId, SeedData.LeftProjectId);
        afterThree.Select(e => e.Date).ShouldBe(afterFirst.Select(e => e.Date));
        afterThree.Select(e => e.BookingId).ShouldBe(afterFirst.Select(e => e.BookingId));

        // ONE EVENT PER DAY still holds across sweeps, which is the thing a re-run could plausibly break.
        afterThree.Select(e => e.Date).ShouldBeUnique();

        // And the sweep is reachable the way the heartbeat reaches it: by sending the message, through
        // the bus, to the same handler. Nothing here posts to the operator route — that route is a
        // convenience for a human, not the mechanism.
        var tracked = await Host.ExecuteAndWaitAsync(async () =>
        {
            using var scope = Host.Services.CreateScope();
            await scope.ServiceProvider.GetRequiredService<IMessageBus>()
                .InvokeAsync(new RunFillZeroHours());
        });
        tracked.Executed.SingleMessage<RunFillZeroHours>().ShouldNotBeNull();
    }
}
